codeExamples.code:
// Synchronous — blocks everything
console.log("1");
// imagine a 3-second delay here
console.log("2");
console.log("3");
// Output: 1, 2, 3 (fast, no delay)

// Asynchronous — non-blocking
console.log("1");
setTimeout(() => console.log("2"), 3000);
console.log("3");
// Output: 1, 3, then after 3s: 2

// CPU-bound: blocks the thread
console.log("start");
let sum = 0;
for (let i = 0; i < 1e9; i++) sum += i;  // slow!
console.log("done: " + sum);  // page freezes until complete

// I/O-bound: non-blocking with async
console.log("fetching...");
fetch("https://api.example.com/data")
  .then(r => r.json())
  .then(data => console.log(data));
console.log("fetch initiated");  // runs immediately!

// One-time timer
let timerId = setTimeout(() => {
  console.log("3 seconds passed!");
}, 3000);

// Cancel before it fires
clearTimeout(timerId);

// Repeating timer
let count = 0;
let intervalId = setInterval(() => {
  count++;
  console.log("Tick: " + count);
  if (count >= 5) clearInterval(intervalId);
}, 1000);
